import { Asset } from 'expo-asset';
import { File } from 'expo-file-system';
import { Platform } from 'react-native';
import type { GenusWarning } from './decision';
import { POISONOUS_SPECIES, TOXIC_GENERA } from './fungiDecision';
import { genusName, scientificName } from './fungiCatalog';

// Wikipedia introductions, generated by ml/export_fungi_info.py. Loaded on first use.
type InfoFile = {
  source: string;
  species: Record<string, [title: string, text: string]>;
  genera: Record<string, [title: string, text: string]>;
};

export type Article = { scope: 'species' | 'genus'; title: string; text: string; url: string; source: string };

export type SpeciesSafety = {
  documented?: { source: string };
  genus?: GenusWarning;
};

let infoPromise: Promise<InfoFile> | null = null;

function loadInfo(): Promise<InfoFile> {
  if (!infoPromise) {
    infoPromise = (async () => {
      // eslint-disable-next-line @typescript-eslint/no-require-imports
      const asset = Asset.fromModule(require('../../assets/fungiInfo.fungiinfo'));
      // The web build has no file system API; it serves the asset over HTTP.
      if (Platform.OS === 'web') return (await (await fetch(asset.uri)).json()) as InfoFile;
      await asset.downloadAsync();
      if (!asset.localUri) throw new Error('Species information is unavailable.');
      return JSON.parse(await new File(asset.localUri).text()) as InfoFile;
    })().catch((error) => {
      infoPromise = null;
      throw error;
    });
  }
  return infoPromise;
}

function wikipediaUrl(title: string): string {
  return `https://en.wikipedia.org/wiki/${encodeURIComponent(title.replace(/ /g, '_'))}`;
}

/** The species' Wikipedia introduction, or its genus's when the species has no article. */
export async function articleFor(species: number): Promise<Article | undefined> {
  const info = await loadInfo();
  const own = info.species[String(species)];
  if (own) return { scope: 'species', title: own[0], text: own[1], url: wikipediaUrl(own[0]), source: info.source };
  const genus = info.genera[genusName(species)];
  if (genus) return { scope: 'genus', title: genus[0], text: genus[1], url: wikipediaUrl(genus[0]), source: info.source };
  return undefined;
}

/** Toxicity this app can cite for a species. An empty result does not mean the species is safe. */
export function safetyFor(species: number): SpeciesSafety {
  const documented = POISONOUS_SPECIES[scientificName(species)];
  const genus = genusName(species);
  const toxic = TOXIC_GENERA[genus];
  return {
    ...(documented ? { documented: { source: documented.source } } : {}),
    ...(toxic ? { genus: { genus, ...toxic } } : {}),
  };
}
